{
  "case_id": "xsu_sg_014_occupational_injury_opinion",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "met", "reason": "Svaret angiver begge kritiske elementer (påvirkning af evnen til at arbejde og om funktionsevnen er så nedsat, at et studiejob ikke kan have) og at udtalelsen er vejledende og ikke bindende for Udbetaling Danmark. Det stemmer med vejledningens afsnit 5.1.3.3 og rubrikken. Ingen væsentlige juridiske fejl."},
    "c02_required_elements_complete": {"label": "met", "reason": "Begge kritiske elementer er med i tilsvarende formulering. Den påkrævede kvalifikation (vejledende, ikke bindende) er også med. Det understøttende element om, at udtalelsen bygger på sagens dokumenter uden undersøgelse, mangler, men det er ikke kritisk."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret besvarer begge dele af spørgsmålet: hvad udtalelsen skal belyse, og om Udbetaling Danmark er bundet."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret nævner ingen kilde (hverken bestemmelse eller vejledningsafsnit)."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så gyldigheden kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så det ikke kan vurderes, om kilder understøtter påstandene."},
    "c07_no_unsupported_legal_additions": {"label": "met", "reason": "Alle udsagn (indhold af vurderingen, vejledende, indgår i den samlede vurdering, ikke bindende) har støtte i afsnit 5.1.3.3. Der er ikke tilføjet uunderstøttede regler."},
    "c08_qualifications_and_exceptions": {"label": "met", "reason": "Den krævede kvalifikation, at udtalelsen er vejledende og ikke binder Udbetaling Danmark, er bevaret."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Svaret er kort og internt konsistent: udtalelsen er vejledende, indgår i den samlede vurdering og binder derfor ikke."},
    "c10_legal_modality_precision": {"label": "met", "reason": "'Skal belyse' svarer til, at AES foretager en vurdering af de to forhold. 'Vejledende' og 'ikke bindende' gengiver kilden korrekt, og der er ingen overdrevne absolutter."}
  },
  "xhaile_coverage": {
    "A68": {"label": "partial", "reason": "Svaret dækker de to vurderingspunkter og den vejledende karakter. Det nævner ikke, at Udbetaling Danmark kan anmode om udtalelsen, at den bygger på sagens dokumentation uden undersøgelse af den uddannelsessøgende, eller at styrelsen betaler udgifterne."}
  },
  "overall_notes": "Indholdsmæssigt korrekt og dækker begge kritiske elementer og den krævede kvalifikation. Svaret har ingen kildehenvisninger, så C04 er not_met, og C05 og C06 er not_assessable. Det udelader desuden de understøttende elementer om sagens dokumenter/ingen undersøgelse, om at udtalelsen indhentes på anmodning, og om betaling af udgifter."
}

